def slv(v, w):
    return '"' + format(v & ((1 << w) - 1), '0%db' % w) + '"'

def rom(name, typ, vals, w, per=16):
    lines = []
    for i in range(0, len(vals), per):
        lines.append('        ' + ', '.join(slv(v, w) for v in vals[i:i + per]))
    return '    constant %s : %s := (\n%s\n    );\n' % (name, typ, ',\n'.join(lines))

